def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration string")

    total_seconds = 0
    current_num = ""

    units = {'h': 3600, 'm': 60, 's': 1}
    valid_chars = set("0123456789hms")

    for char in s:
        if char in "0123456789":
            current_num += char
        elif char in units:
            if not current_num:
                raise ValueError(f"Missing number before unit '{char}'")
            total_seconds += int(current_num) * units[char]
            current_num = ""
        else:
            raise ValueError(f"Invalid character '{char}' in duration string")

    if current_num:
        raise ValueError("Duration string must end with a unit (h, m, or s)")

    return total_seconds
